def are_equivalent_zones(zone1: str, zone2: str) -> bool:
    # Different lengths cannot be anagrams
    if len(zone1) != len(zone2):
        return False

    freq = [0] * 26  # frequency array for 'a' to 'z'

    for ch in zone1:
        freq[ord(ch) - ord('a')] += 1  # count chars in zone1

    for ch in zone2:
        freq[ord(ch) - ord('a')] -= 1  # subtract chars in zone2

    # All counts must be zero for anagram
    return all(count == 0 for count in freq)

