def longest_balanced_window(orders: str) -> int:
    n = len(orders)
    max_len = 0

    for i in range(n):
        seen = set()
        for j in range(i, n):
            seen.add(orders[j])
            if len(seen) > 2:
                break
            max_len = max(max_len, j - i + 1)

    return max_len
